/// How often the RSS sampler walks the process table while the child runs.
///
/// 200 ms is a deliberate floor, not a tuning knob left at its default. A full `refresh_processes`
/// walk is the expensive part, and a build is minutes long: at 200 ms a two-minute build costs ~600
/// walks, which is noise beside the compile, while a 20 ms sampler would cost 6000 and start competing
/// with the thing it is measuring. The cost being measured is a build, and a build's memory moves on
/// the scale of a rustc process starting — hundreds of milliseconds, not microseconds.
const SAMPLE_INTERVAL_MS: u64 = 200;

/// Windows' `STATUS_CONTROL_C_EXIT` (0xC000013A) as `ExitStatus::code` reports it — the raw `u32`
/// reinterpreted as `i32`, which is what it becomes on the way through. Written as the cast rather
/// than the decimal so it is recognizable as the documented NTSTATUS and not a magic number.
const WINDOWS_CTRL_C: i32 = 0xC000013A_u32 as i32;

/// Exit codes that mean INTERRUPTED rather than failed, on the platforms that report it as a code.
/// 130 = 128+SIGINT and 143 = 128+SIGTERM, which is how a shell relays a signal it caught for you.
const INTERRUPT_CODES: [i32; 3] = [130, 143, WINDOWS_CTRL_C];

/// What a finished run amounts to — everything the caller needs to decide, with no I/O left in it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Outcome {
    /// The child's exit code, or `None` if it was killed by a signal without one.
    pub code: Option<i32>,
    /// Killed by a signal, or exited with a code that means the same thing.
    pub interrupted: bool,
}

impl Outcome {
    /// Did this run FAIL, in the sense that is worth recording?
    ///
    /// An interrupt is not a failure. `vite` under a dev server exits 130 on Ctrl-C, and a wrapper that
    /// filed a fault every time a developer stopped their dev server would train everyone to ignore the
    /// store — which is the only way this feature actually dies.
    pub fn is_fault(&self) -> bool {
        !self.interrupted && self.code != Some(0)
    }
    /// Did it SUCCEED, in the sense that clears what this source recorded before?
    ///
    /// Deliberately not `!is_fault()`: an interrupted run proves nothing either way, so it must not
    /// clear a real fault recorded by the last real run.
    pub fn is_clean(&self) -> bool {
        self.code == Some(0)
    }
    /// The code to exit this process with. A signal death has no code of its own; 130 is the
    /// conventional stand-in and is what a shell would have reported.
    pub fn exit_code(&self) -> i32 {
        self.code.unwrap_or(130)
    }
}

/// Classify a finished child. Split out from the spawn so the signal rule is testable without one.
fn classify(status: &std::process::ExitStatus) -> Outcome {
    #[cfg(unix)]
    let signalled = {
        use std::os::unix::process::ExitStatusExt;
        status.signal().is_some()
    };
    #[cfg(not(unix))]
    let signalled = false;

    let code = status.code();
    let interrupted = signalled || code.is_some_and(|c| INTERRUPT_CODES.contains(&c));
    Outcome { code, interrupted }
}

/// Spawn `cmd`, forwarding both streams live while accumulating them, and return the outcome plus the
/// combined output.
///
/// The two streams are merged into ONE buffer in arrival order, which is what the extractor wants: a
/// cargo diagnostic is on stderr while a bundler's is on stdout, and a producer that captured only one
/// would silently see nothing for half the tools it wraps.
/// What a run cost, as opposed to whether it worked.
///
/// Both fields are OPTIONAL and that is load-bearing: a measurement that could not be taken must read
/// as absent, never as zero. A build recorded at 0 ms or 0 bytes would enter a median and pull it
/// toward a number nothing observed — the same reason `bsc perf compare` reports an empty half as
/// absent rather than as fast.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Cost {
    /// Wall clock from spawn to reap, in milliseconds.
    pub ms: Option<i64>,
    /// The PEAK, over the run, of the SUMMED resident memory of the child and every descendant.
    pub peak_rss_bytes: Option<i64>,
}

/// The peak of the summed RSS of the process tree rooted at `root`, sampled until `done` is set.
///
/// ## Why the SUM of the tree and not the child
///
/// The child of a build wrapper is `cargo` or `npm`, and neither holds the memory: `rustc` and
/// `esbuild` descendants do. Sampling only the direct child would report a few megabytes for a build
/// that peaks at eight gigabytes. And it must be the sum ACROSS the tree at one moment rather than the
/// largest single process, because what exhausts the machine is everything resident at once — which is
/// also what the figures already in CLAUDE.md mean (8.04 GB at `jobs = 4` is four concurrent rustc
/// processes, not one 8 GB process), so keeping the same definition makes this number comparable to
/// the ones already written down rather than a second incompatible metric.
///
/// ## ⚠️ THREADS ARE LISTED AS PROCESSES AND CARRY THE PARENT'S RSS
///
/// On Linux `sysinfo` yields a process's threads alongside real processes, each reporting the parent's
/// `VmRSS`. Summing the table naively multiplies a process by its thread count — this repo has already
/// paid for that once, in the webview sampler, where two entries reported an identical 1319 MB for a
/// single real process (see `classify_process` in `observability/perf.rs`). `thread_kind().is_some()`
/// is the filter that makes the sum mean something, and it is not optional.
fn sample_tree_peak(root: u32, done: Arc<AtomicBool>, out: Arc<AtomicU64>) {
    use sysinfo::{Pid, ProcessRefreshKind, ProcessesToUpdate, System};
    let mut sys = System::new();
    let root = Pid::from(root as usize);
    while !done.load(Ordering::Relaxed) {
        sys.refresh_processes_specifics(
            ProcessesToUpdate::All,
            true,
            ProcessRefreshKind::nothing().with_memory(),
        );
        // Walk DOWN from the root each tick rather than trusting a pid set from a previous one: a build
        // spawns and reaps compilers continuously, so any cached set is stale by the next sample.
        // ⚠️ THE CHILD INDEX IS BUILT ONCE PER TICK, and that is a CORRECTNESS fix rather than a
        // micro-optimization. Scanning the whole process table for each frontier node is O(nodes × n),
        // and a workspace `cargo clippy` puts hundreds of processes on the machine — so one tick could
        // take longer than the sampling interval itself, and the sampler would MISS the short-lived
        // rustc processes that hold the memory. MEASURED before this fix: a full-workspace clippy
        // reported a 179 MB peak, against 943 MB for a `tsc` run that spawns almost nothing — an
        // ordering that cannot be true. Indexing first makes a tick O(n) and the peak believable.
        let mut children: std::collections::HashMap<Pid, Vec<Pid>> = std::collections::HashMap::new();
        for (pid, proc_) in sys.processes() {
            if let Some(parent) = proc_.parent() {
                children.entry(parent).or_default().push(*pid);
            }
        }
        let mut total: u64 = 0;
        let mut frontier = vec![root];
        let mut seen = std::collections::HashSet::new();
        while let Some(pid) = frontier.pop() {
            if !seen.insert(pid) {
                continue;
            }
            if let Some(proc_) = sys.process(pid) {
                // A thread reports its parent's RSS — counting it would multiply the parent by its
                // thread count. See this function's doc.
                if proc_.thread_kind().is_none() {
                    total = total.saturating_add(proc_.memory());
                }
            }
            if let Some(kids) = children.get(&pid) {
                frontier.extend(kids.iter().copied());
            }
        }
        out.fetch_max(total, Ordering::Relaxed);
        std::thread::sleep(std::time::Duration::from_millis(SAMPLE_INTERVAL_MS));
    }
}

fn spawn_and_tee(cmd: &[String]) -> Result<(Outcome, String, Cost), String> {
    let (prog, rest) = cmd.split_first().ok_or("run: no command given")?;
    let started = std::time::Instant::now();
    let mut child = Command::new(prog)
        .args(rest)
        .stdin(Stdio::inherit())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("run: cannot start `{prog}`: {e}"))?;

    // The sampler starts only once the child EXISTS, so its pid is real and the first walk can already
    // see it. It is detached from the outcome entirely: if this thread panics or the process table is
    // unreadable, `peak` stays 0 and is reported as ABSENT below, never as a measurement of zero.
    let done = Arc::new(AtomicBool::new(false));
    let peak = Arc::new(AtomicU64::new(0));
    let sampler = {
        let (done, peak, pid) = (done.clone(), peak.clone(), child.id());
        std::thread::spawn(move || sample_tree_peak(pid, done, peak))
    };

    let buf = Arc::new(Mutex::new(String::new()));
    let out = child.stdout.take().map(|s| pump(s, buf.clone(), false));
    let err = child.stderr.take().map(|s| pump(s, buf.clone(), true));

    let status = child.wait().map_err(|e| format!("run: waiting for `{prog}`: {e}"))?;
    // Join AFTER the wait: the pumps end when their pipes close, and joining first would deadlock on a
    // child that outlives its own output.
    for t in [out, err].into_iter().flatten() {
        let _ = t.join();
    }
    // Stop sampling only after the reap, so the final tick still sees a tree that was alive a moment
    // ago. Joining is bounded by one sleep interval and cannot hang the wrapper.
    done.store(true, Ordering::Relaxed);
    let _ = sampler.join();

    let text = buf.lock().unwrap_or_else(|e| e.into_inner()).clone();
    let observed = peak.load(Ordering::Relaxed);
    let cost = Cost {
        ms: i64::try_from(started.elapsed().as_millis()).ok(),
        // ZERO MEANS "NEVER OBSERVED", not "used no memory" — a live process always has some resident
        // memory, so the only way this is 0 is that no sample ever landed (a run shorter than the first
        // tick, or an unreadable process table). Reported absent, for the reason on `Cost`.
        peak_rss_bytes: (observed > 0).then(|| i64::try_from(observed).unwrap_or(i64::MAX)),
    };
    Ok((classify(&status), text, cost))
}

/// Run a command for its COST ALONE — no output capture, no fault detection.
///
/// ## Why this is a separate path and not a flag on the tee
///
/// The tee has to PIPE stdout and stderr, because reading them is how a fault's diagnostic is
/// extracted. Piping has a price this file already states: a tool that colorizes only for a terminal
/// stops, and one that draws a live progress bar loses it. That price is worth paying to capture a
/// failure — and NOT worth paying when the only thing wanted is a number.
///
/// The gate is the caller that makes this concrete. It runs cargo for minutes and deliberately uses
/// inherited stdio so the compile streams live, because a gate that looks frozen is a gate people
/// stop running. It also must NOT file faults — `CLAUDE.md` says so outright: ten worktree agents
/// gating in parallel would pin every project node red and destroy the signal. So the gate wants
/// exactly cost and exactly nothing else, which is this.
///
/// The SAMPLER is unaffected by any of that: it watches the process tree by pid and never touches the
/// child's streams. So this still measures wall clock and peak RSS in full.
fn spawn_measured(cmd: &[String]) -> Result<(Outcome, Cost), String> {
    let (prog, rest) = cmd.split_first().ok_or("run: no command given")?;
    let started = std::time::Instant::now();
    let mut child = Command::new(prog)
        .args(rest)
        // INHERITED, all three — that is the difference from `spawn_and_tee`, and the reason this
        // exists at all.
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|e| format!("run: cannot start `{prog}`: {e}"))?;

    let done = Arc::new(AtomicBool::new(false));
    let peak = Arc::new(AtomicU64::new(0));
    let sampler = {
        let (done, peak, pid) = (done.clone(), peak.clone(), child.id());
        std::thread::spawn(move || sample_tree_peak(pid, done, peak))
    };

    let status = child.wait().map_err(|e| format!("run: waiting for `{prog}`: {e}"))?;
    done.store(true, Ordering::Relaxed);
    let _ = sampler.join();

    let observed = peak.load(Ordering::Relaxed);
    Ok((
        classify(&status),
        Cost {
            ms: i64::try_from(started.elapsed().as_millis()).ok(),
            peak_rss_bytes: (observed > 0).then(|| i64::try_from(observed).unwrap_or(i64::MAX)),
        },
    ))
}

/// Forward one pipe line-by-line to our own stream while appending it to the shared buffer.
fn pump<R: std::io::Read + Send + 'static>(
    r: R,
    buf: Arc<Mutex<String>>,
    to_stderr: bool,
) -> std::thread::JoinHandle<()> {
    std::thread::spawn(move || {
        let mut reader = BufReader::new(r);
        let mut line = String::new();
        loop {
            line.clear();
            // read_line, not lines(): a build tool's last line may have no newline, and `lines()`
            // would still yield it but a `read_to_string` at the end would have shown nothing until
            // the process died. Lossy on purpose — a build log is not guaranteed UTF-8 and a decode
            // error must not lose the diagnostic.
            let mut raw = Vec::new();
            match reader.read_until(b'\n', &mut raw) {
                Ok(0) | Err(_) => break,
                Ok(_) => {}
            }
            let text = String::from_utf8_lossy(&raw).to_string();
            if to_stderr {
                let mut h = std::io::stderr().lock();
                let _ = h.write_all(text.as_bytes());
                let _ = h.flush();
            } else {
                let mut h = std::io::stdout().lock();
                let _ = h.write_all(text.as_bytes());
                let _ = h.flush();
            }
            if let Ok(mut b) = buf.lock() {
                b.push_str(&text);
            }
        }
    })
}

/// What [`decide`] concluded should happen to the store — pure, so the whole policy is testable
/// without spawning anything or opening a db.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Action {
    /// Record this fault.
    Record { title: String, detail: Option<String> },
    /// The run succeeded — clear whatever this source recorded before.
    Clear,
    /// Do nothing (an interrupt).
    Nothing,
}

/// [`run_and_record`], with `measure_only` selecting the cost-only path described on [`spawn_measured`].
///
/// One function rather than two so the exit-code contract — propagate the child's own code, exactly,
/// by exiting this process — cannot drift between the two modes. That contract is the reason callers
/// can chain on `&&` at all, and having it written twice is how it would eventually differ.
pub fn run_with(
    cmd: &[String],
    db: Option<&std::path::Path>,
    stage: &str,
    source: &str,
    level: &str,
    now_ms: i64,
    measure_only: bool,
) -> Result<std::convert::Infallible, String> {
    if measure_only {
        let (outcome, cost) = spawn_measured(cmd)?;
        let recorded = db.is_some_and(|path| record_run(path, &cost, &outcome, stage, source, cmd, now_ms));
        // The ONE thing this mode used to leave unsaid. `measure_ack` decides whether there is anything
        // honest to say (an interrupt is not a measurement); the destination is stderr, so the child's
        // stdout stays byte-identical and every pipeline through this wrapper is unaffected.
        if let Some(ack) = measure_ack(source, &cost, &outcome, recorded, db) {
            let _ = writeln!(std::io::stderr(), "{ack}");
        }
        let _ = std::io::stdout().flush();
        let _ = std::io::stderr().flush();
        std::process::exit(outcome.exit_code());
    }
    let (outcome, output, cost) = spawn_and_tee(cmd)?;
    // Everything from here is best-effort: the child has run, and nothing below may change what the
    // caller sees beyond one extra line on stderr saying where the fault went.
    if let Some(path) = db {
        let action = decide(&outcome, &output, cmd);
        if let Some(note) = apply_to_store(path, &action, stage, source, level, cmd, now_ms) {
            let _ = writeln!(std::io::stderr(), "{note}");
        }
        // Cost is recorded for the CLEAN runs too, so it is deliberately not inside the branch above —
        // `decide` returns `Clear` for a success and there would be nothing to hang this off.
        record_run(path, &cost, &outcome, stage, source, cmd, now_ms);
    }
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
    std::process::exit(outcome.exit_code());
}

#[cfg(test)]
mod tests {
    use super::*;

    fn out(code: Option<i32>, interrupted: bool) -> Outcome {
        Outcome { code, interrupted }
    }
    fn cmd() -> Vec<String> {
        vec!["cargo".into(), "build".into()]
    }

    /// The rule that keeps the store readable: stopping a dev server is not a defect.
    #[test]
    fn an_interrupt_records_nothing_and_clears_nothing() {
        for o in [out(None, true), out(Some(130), true), out(Some(143), true)] {
            assert_eq!(decide(&o, "error: boom", &cmd()), Action::Nothing, "{o:?}");
        }
        // An interrupt must not CLEAR either — it proves nothing about whether the last real failure
        // is fixed, and clearing on it would quietly erase a live fault.
        assert!(!out(Some(130), true).is_clean());
    }

    /// Every non-zero code is a failure — including cargo's 101, which is the common one here.
    #[test]
    fn a_real_failure_records_the_extracted_diagnostic() {
        let o = out(Some(101), false);
        let a = decide(&o, "   Compiling x\nerror[E0308]: mismatched types\n --> a.rs:1:1", &cmd());
        match a {
            Action::Record { title, detail } => {
                assert_eq!(title, "error[E0308]: mismatched types");
                assert!(detail.unwrap().contains("a.rs"), "the location rides in the detail");
            }
            other => panic!("expected a record, got {other:?}"),
        }
    }

    /// A failure with nothing readable still records — naming the command, because there is genuinely
    /// nothing else to say and silence here would be the same as not having the feature.
    #[test]
    fn an_unreadable_failure_records_the_command_rather_than_nothing() {
        let a = decide(&out(Some(127), false), "", &cmd());
        match a {
            Action::Record { title, detail } => {
                assert!(title.contains("cargo build") && title.contains("127"), "{title}");
                assert_eq!(detail, None, "there is no detail to invent");
            }
            other => panic!("expected a record, got {other:?}"),
        }
    }

    #[test]
    fn a_clean_run_clears_what_this_source_recorded() {
        assert_eq!(decide(&out(Some(0), false), "", &cmd()), Action::Clear);
    }

    /// The exit code is the child's, exactly — a caller chaining on `&&` must see what it would have
    /// seen unwrapped.
    #[test]
    fn the_exit_code_is_the_childs_own() {
        assert_eq!(out(Some(101), false).exit_code(), 101);
        assert_eq!(out(Some(0), false).exit_code(), 0);
        // A signal death has no code; 130 is what a shell would have reported.
        assert_eq!(out(None, true).exit_code(), 130);
    }

    /// The tee really runs a process, forwards it, and captures both streams merged — the property
    /// the extractor depends on, since cargo diagnoses on stderr and bundlers on stdout.
    #[test]
    fn spawn_captures_both_streams_and_the_real_exit_code() {
        let sh = if cfg!(windows) { "cmd" } else { "sh" };
        let args: Vec<String> = if cfg!(windows) {
            vec!["cmd".into(), "/C".into(), "echo out& echo err 1>&2& exit 3".into()]
        } else {
            vec![sh.into(), "-c".into(), "echo out; echo err 1>&2; exit 3".into()]
        };
        let (o, text, _cost) = spawn_and_tee(&args).expect("spawns");
        assert_eq!(o.code, Some(3), "the child's real code");
        assert!(!o.interrupted);
        assert!(text.contains("out") && text.contains("err"), "both streams captured: {text:?}");
    }

    /// The write path end to end: a failing run lands ONE row, a second identical failure bumps its
    /// count rather than adding a row, and a passing run clears it.
    #[test]
    fn record_then_clear_round_trips_against_a_real_store() {
        let dir = std::env::temp_dir().join(format!("errordb-run-{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("error.db");
        let _ = std::fs::remove_file(&path);
        let c = cmd();
        let fail = out(Some(101), false);
        let log = "error[E0308]: mismatched types\n --> a.rs:1:1";

        let note = apply_to_store(&path, &decide(&fail, log, &c), "compile", "build:plan", "error", &c, 10);
        assert!(note.unwrap().contains("recorded compile fault"));
        // The same break at another line is the SAME fault — count 2, still one row.
        apply_to_store(&path, &decide(&fail, "error[E0308]: mismatched types\n --> a.rs:9:9", &c), "compile", "build:plan", "error", &c, 20);
        let store = crate::Store::open(&path).unwrap();
        let open = store.list(&crate::Filter { unresolved: true, ..Default::default() }).unwrap();
        assert_eq!(open.len(), 1, "one fault row");
        assert_eq!(open[0].count, 2, "a repeat bumps the count");
        assert_eq!(open[0].source_hint.as_deref(), Some("build:plan"));
        assert!(open[0].title.starts_with("error[E0308]"), "the title is the diagnostic, not the command");

        // ...and the fix clears it.
        let note = apply_to_store(&path, &decide(&out(Some(0), false), "", &c), "compile", "build:plan", "error", &c, 30);
        assert!(note.unwrap().contains("cleared 1"));
        assert!(store.list(&crate::Filter { unresolved: true, ..Default::default() }).unwrap().is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A green run clears ONLY what its own source recorded. Two producers writing the same stage must
    /// not clear each other, or a passing build would silently resolve a failing typecheck.
    #[test]
    fn a_clean_run_never_clears_another_sources_fault() {
        let dir = std::env::temp_dir().join(format!("errordb-run-src-{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("error.db");
        let _ = std::fs::remove_file(&path);
        let c = cmd();
        let fail = decide(&out(Some(1), false), "error: boom", &c);
        apply_to_store(&path, &fail, "build", "mine", "error", &c, 10);
        apply_to_store(&path, &decide(&out(Some(1), false), "error: other", &c), "build", "theirs", "error", &c, 11);

        apply_to_store(&path, &Action::Clear, "build", "mine", "error", &c, 20);
        let store = crate::Store::open(&path).unwrap();
        let open = store.list(&crate::Filter { unresolved: true, ..Default::default() }).unwrap();
        assert_eq!(open.len(), 1, "only the other source's fault is left");
        assert_eq!(open[0].source_hint.as_deref(), Some("theirs"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The first failure on a machine that has never had this project creates its hub, rather than
    /// silently recording nothing.
    ///
    /// Worth pinning because the fail-open rule above makes the opposite indistinguishable from
    /// working: a missing `projects/<key>/` directory would just mean no note and no row, forever, on
    /// exactly the fresh checkout where the first build failure is most likely.
    #[test]
    fn the_first_fault_creates_a_hub_that_does_not_exist_yet() {
        let base = std::env::temp_dir().join(format!("errordb-run-fresh-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        let path = base.join("projects").join("brand-new").join("error.db");
        assert!(!path.exists());
        let c = cmd();
        let a = decide(&out(Some(1), false), "error: boom", &c);
        assert!(apply_to_store(&path, &a, "build", "s", "error", &c, 1).is_some(), "it recorded");
        assert!(path.is_file(), "the hub and its store were created: {}", path.display());
        let _ = std::fs::remove_dir_all(&base);
    }

    /// Fail-open: a store that genuinely cannot be opened is silent. It cannot panic, and it cannot
    /// produce a note that would read as if something had been recorded.
    ///
    /// (Unopenable, not merely absent — the path below is under a root nothing may create in. An absent
    /// directory is created, which is the test above.)
    #[test]
    fn an_unopenable_store_records_nothing_and_says_nothing() {
        let bad = std::path::Path::new("/definitely/not/a/directory/9f3a/error.db");
        let c = cmd();
        let a = decide(&out(Some(1), false), "error: boom", &c);
        assert_eq!(apply_to_store(bad, &a, "build", "s", "error", &c, 1), None);
        assert_eq!(apply_to_store(bad, &Action::Clear, "build", "s", "error", &c, 1), None);
    }

    /// A command that cannot START is the caller's error, not a fault: there is no failing build to
    /// record, and filing one would attribute a typo in the wrapper to the project.
    #[test]
    fn a_command_that_cannot_start_is_an_error_not_a_fault() {
        let err = spawn_and_tee(&["definitely-not-a-real-binary-9f3a".to_string()]).unwrap_err();
        assert!(err.contains("cannot start"), "{err}");
    }

    // ── what a run COST ──────────────────────────────────────────────────────────────────────────

    /// Wall clock is measured even for a command that does nothing, and it is measured as a DURATION
    /// rather than left at the default — a `Some(0)` here would be indistinguishable from "not taken".
    #[test]
    fn a_run_is_timed() {
        let args = if cfg!(windows) {
            vec!["cmd".into(), "/C".into(), "echo hi".into()]
        } else {
            vec!["sh".into(), "-c".into(), "echo hi".into()]
        };
        let (_o, _t, cost) = spawn_and_tee(&args).expect("spawns");
        assert!(cost.ms.is_some(), "a completed run always has a wall clock");
    }

    /// THE DESCENDANT RULE, which is the whole reason the sampler walks a tree rather than reading one
    /// process — and it is asserted so that the WRONG implementation fails it.
    ///
    /// The direct child here is `sh`, which holds single-digit megabytes. The memory belongs to the
    /// GRANDCHILD, which allocates 300 MB and holds it across several sample ticks. A sampler that read
    /// only `child.id()` would report ~3 MB; the floor below is 100 MB, so the two answers cannot both
    /// pass. That gap is the point: an assertion both versions satisfy would be evidence of nothing.
    ///
    /// `node` is the allocator because this repo already requires it (vitest, every npm script), so it
    /// is present wherever these tests run. A missing peak FAILS rather than skipping — an unmeasurable
    /// sampler is exactly the regression this test exists to catch, and a silent skip would hide it.
    #[cfg(unix)]
    #[test]
    fn the_peak_counts_a_descendant_not_only_the_direct_child() {
        const MB: i64 = 1024 * 1024;
        let hog = "node -e 'const b=Buffer.alloc(300*1024*1024); b.fill(1); \
                   const t=Date.now(); while(Date.now()-t<1500){}'";
        let args = vec!["sh".into(), "-c".into(), hog.to_string()];
        let (outcome, text, cost) = spawn_and_tee(&args).expect("spawns");
        assert!(outcome.is_clean(), "the allocator ran: {text}");

        let peak = cost
            .peak_rss_bytes
            .expect("the sampler must observe a 1.5s run — an absent peak here is the regression");
        assert!(
            peak > 100 * MB,
            "the grandchild's 300 MB must be counted; {} MB is what reading only the direct `sh` \
             would report",
            peak / MB,
        );
    }

    /// An unobserved peak is ABSENT, never zero. A live process always holds some resident memory, so
    /// a recorded `0` could only ever mean "no sample landed" — and a zero entering a median pulls it
    /// toward a number nothing measured.
    #[test]
    fn an_unobserved_peak_is_absent_rather_than_zero() {
        let cost = Cost { ms: Some(5), peak_rss_bytes: None };
        assert_eq!(cost.peak_rss_bytes, None);
        assert_ne!(cost.peak_rss_bytes, Some(0), "absent and zero are different answers");
    }

    /// A CLEAN run is recorded, which `faults` deliberately never does — the trend needs the green runs
    /// or it cannot answer whether the build is getting slower.
    #[test]
    fn a_clean_run_is_recorded_with_its_cost() {
        let dir = std::env::temp_dir().join(format!("errordb-runs-clean-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = dir.join("error.db");

        let cost = Cost { ms: Some(1234), peak_rss_bytes: Some(8_589_934_592) };
        let clean = out(Some(0), false);
        assert!(record_run(&db, &cost, &clean, "build", "npm-build", &cmd(), 42));

        let store = crate::Store::open(&db).unwrap();
        let (ok, ms, peak, stage): (i64, i64, i64, String) = store
            .conn
            .query_row("SELECT ok, ms, peak_rss_bytes, stage FROM runs", [], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?))
            })
            .unwrap();
        assert_eq!((ok, ms, peak, stage.as_str()), (1, 1234, 8_589_934_592, "build"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A FAILED run is recorded too — a failure that took ten minutes and 12 GB before dying is a cost
    /// worth seeing, and dropping it would bias the trend toward the runs that happened to succeed.
    #[test]
    fn a_failed_run_is_recorded_and_carries_its_exit_code() {
        let dir = std::env::temp_dir().join(format!("errordb-runs-fail-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = dir.join("error.db");

        let cost = Cost { ms: Some(9), peak_rss_bytes: None };
        assert!(record_run(&db, &cost, &out(Some(101), false), "build", "cargo", &cmd(), 7));

        let store = crate::Store::open(&db).unwrap();
        let (ok, code, ms, peak): (i64, i64, i64, Option<i64>) = store
            .conn
            .query_row("SELECT ok, exit_code, ms, peak_rss_bytes FROM runs", [], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?))
            })
            .unwrap();
        assert_eq!((ok, code, ms), (0, 101, 9));
        assert_eq!(peak, None, "an absent peak round-trips as NULL, not as 0");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// An INTERRUPT is not a measurement. Ctrl-C part-way through a build gives a wall clock that is
    /// however long someone waited before giving up — a fast cheap build, as far as any trend can tell.
    /// The same judgment `is_fault` already makes for faults.
    #[test]
    fn an_interrupted_run_records_no_cost() {
        let dir = std::env::temp_dir().join(format!("errordb-runs-int-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = dir.join("error.db");

        let cost = Cost { ms: Some(3), peak_rss_bytes: Some(1) };
        assert!(!record_run(&db, &cost, &out(Some(130), true), "build", "s", &cmd(), 1));

        let store = crate::Store::open(&db).unwrap();
        let n: i64 = store.conn.query_row("SELECT COUNT(*) FROM runs", [], |r| r.get(0)).unwrap();
        assert_eq!(n, 0, "an interrupted run is not a cost sample");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Recording is FAIL-OPEN, the same rule `apply_to_store` states: an unopenable store is a silent
    /// no-op, never an error the caller could mistake for the command's own failure.
    #[test]
    fn an_unopenable_store_records_no_run_and_says_nothing() {
        let nowhere = std::path::Path::new("/definitely/not/a/dir/9f3a/error.db");
        assert!(!record_run(nowhere, &Cost::default(), &out(Some(0), false), "build", "s", &cmd(), 1));
    }

    /// MEASURE-ONLY still measures. The sampler watches the process tree by pid and never touches the
    /// child's streams, so inheriting stdio costs nothing in measurement — which is the whole claim
    /// that lets the gate keep its live cargo progress AND get a number.
    #[cfg(unix)]
    #[test]
    fn measure_only_still_measures_the_tree_without_capturing_output() {
        const MB: i64 = 1024 * 1024;
        let hog = "node -e 'const b=Buffer.alloc(300*1024*1024); b.fill(1); \
                   const t=Date.now(); while(Date.now()-t<1200){}'";
        let args = vec!["sh".into(), "-c".into(), hog.to_string()];
        let (outcome, cost) = spawn_measured(&args).expect("spawns");
        assert!(outcome.is_clean());
        let peak = cost.peak_rss_bytes.expect("an unmeasured 1.2s run is the regression this catches");
        assert!(peak > 100 * MB, "the descendant is counted here too: {} MB", peak / MB);
        assert!(cost.ms.unwrap_or(0) >= 1000, "and it is timed: {:?}", cost.ms);
    }

    /// The exit code contract is IDENTICAL on both paths. Callers chain on `&&`; a mode that flattened
    /// 101 to 1 would break that silently, and the two paths having separate spawn code is exactly how
    /// such a difference creeps in.
    #[cfg(unix)]
    #[test]
    fn measure_only_classifies_an_exit_code_the_same_way_the_tee_does() {
        for code in [0, 1, 101] {
            let args = vec!["sh".into(), "-c".into(), format!("exit {code}")];
            let (measured, _) = spawn_measured(&args).expect("spawns");
            let (teed, _, _) = spawn_and_tee(&args).expect("spawns");
            assert_eq!(measured, teed, "both paths must agree about exit {code}");
            assert_eq!(measured.exit_code(), code);
        }
    }

    // ── the --measure-only acknowledgment (`measure-only-tells-the-caller-what-it-recorded`) ────────

    fn hub_db() -> std::path::PathBuf {
        std::path::PathBuf::from("/home/u/.base-studio-code/projects/studio-code/error.db")
    }
    fn cost(ms: Option<i64>, peak: Option<i64>) -> Cost {
        Cost { ms, peak_rss_bytes: peak }
    }

    /// THE REGRESSION THIS EXISTS FOR: a clean measured run said nothing at all, so the one caller whose
    /// job is to report a cost had none. The line must carry the tag it was measured under, the wall
    /// clock, and a command that actually runs.
    #[test]
    fn a_clean_measured_run_reports_its_cost_and_how_to_read_the_trend() {
        let ack = measure_ack("op:studio:list", &cost(Some(432), Some(1_427_664_896)), &out(Some(0), false), true, Some(&hub_db()))
            .expect("a clean measured run has something to say");
        assert!(ack.contains("op:studio:list"), "the source tag is how the trend is filtered: {ack}");
        assert!(ack.contains("0.4s"), "the wall clock, in `bsc mem build`'s own units: {ack}");
        assert!(ack.contains("peak 1362 MB"), "{ack}");
        assert!(
            ack.contains("bsc mem build --project studio-code --source op:studio:list"),
            "the read-back must be a command that RUNS, not a description of one: {ack}"
        );
    }

    /// A hub db names its project KEY, so the suggestion matches what the caller typed rather than
    /// handing back a path it never mentioned.
    #[test]
    fn a_project_hub_db_is_named_by_its_key_and_anything_else_by_its_path() {
        assert_eq!(
            mem_read_back(&hub_db(), "gate:clippy"),
            "bsc mem build --project studio-code --source gate:clippy"
        );
        // Not a hub layout ⇒ the exact --db form, which is always correct. Deriving a key from a path
        // that is not `projects/<key>/error.db` would point the reader at a store that may not exist.
        let loose = std::path::PathBuf::from("/tmp/scratch/error.db");
        assert_eq!(
            mem_read_back(&loose, "gate:clippy"),
            "bsc mem build --db /tmp/scratch/error.db --source gate:clippy"
        );
        let renamed = std::path::PathBuf::from("/home/u/.base-studio-code/projects/studio-code/other.db");
        assert!(mem_read_back(&renamed, "s").starts_with("bsc mem build --db "), "only error.db is a hub db");
    }

    /// ABSENT IS NOT ZERO, and the reader must be able to tell "no sample" from "write failed".
    /// MEASURED: 10 of 10 runs of a 0.4s command recorded no peak, because the sampler walks at 200 ms.
    #[test]
    fn an_unsampled_peak_says_so_rather_than_reporting_zero() {
        let ack = measure_ack("op:studio:list", &cost(Some(432), None), &out(Some(0), false), true, Some(&hub_db()))
            .expect("still an acknowledgment");
        assert!(ack.contains("peak not sampled"), "{ack}");
        assert!(!ack.contains("0 MB"), "a zero would enter the reader's head as a measurement: {ack}");
        // And an unmeasurable wall clock reads the same way, for the same reason.
        let no_time = measure_ack("s", &cost(None, None), &out(Some(0), false), true, Some(&hub_db())).expect("ack");
        assert!(no_time.contains("time not measured"), "{no_time}");
        assert!(!no_time.contains("0.0s"), "{no_time}");
    }

    /// A run whose cost went nowhere must SAY so. Staying silent is what left ten recorded runs
    /// indistinguishable from ten that vanished.
    #[test]
    fn a_cost_that_was_not_recorded_is_reported_as_not_recorded() {
        let no_store = measure_ack("s", &cost(Some(10), None), &out(Some(0), false), false, None).expect("ack");
        assert!(no_store.contains("NOT recorded"), "{no_store}");
        assert!(no_store.contains("--project"), "it must name the flag that fixes it: {no_store}");

        let failed = measure_ack("s", &cost(Some(10), None), &out(Some(0), false), false, Some(&hub_db())).expect("ack");
        assert!(failed.contains("NOT recorded"), "{failed}");
        assert!(failed.contains("error.db"), "name the store it could not write: {failed}");
        assert!(failed.contains("exit code is unchanged"), "fail-open must be stated, not assumed: {failed}");
    }

    /// An interrupt is not a measurement — `record_run` already refuses one, and the ack must not
    /// announce a cost that no row holds.
    #[test]
    fn an_interrupted_run_acknowledges_nothing() {
        for o in [out(None, true), out(Some(130), true), out(Some(143), true)] {
            assert_eq!(measure_ack("s", &cost(Some(9_000), Some(1)), &o, false, Some(&hub_db())), None, "{o:?}");
        }
    }

    /// A FAILED run still cost something, and the trend is about cost, not correctness. `record_run`
    /// records it, so the ack must report it rather than treating a non-zero exit as nothing to say.
    #[test]
    fn a_failed_but_uninterrupted_run_still_reports_its_cost() {
        let ack = measure_ack("gate:clippy", &cost(Some(90_000), None), &out(Some(101), false), true, Some(&hub_db()))
            .expect("a failure has a cost");
        assert!(ack.contains("90.0s"), "{ack}");
        assert!(ack.contains("recorded"), "{ack}");
    }

    /// EVERY line is prefixed, so a caller reading a merged stream can tell the wrapper's own words
    /// from the child's — the wrapped command's stdout is untouched and this is the only thing that
    /// distinguishes them.
    #[test]
    fn every_acknowledgment_line_is_prefixed_as_the_wrappers_own() {
        let ack = measure_ack("s", &cost(Some(1), Some(1)), &out(Some(0), false), true, Some(&hub_db())).expect("ack");
        assert!(ack.lines().count() >= 2, "the cost and the read-back are separate lines: {ack}");
        for line in ack.lines() {
            assert!(line.starts_with("[measured] "), "unprefixed line {line:?} in {ack}");
        }
    }
}

